import React, { useState } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import {faEnvelope, faUser, faBriefcase} from "@fortawesome/free-solid-svg-icons";
export default function MailOptions() {
  const [isModalOpen, setIsModalOpen] = useState(false);

  const handleOpenModal = () => setIsModalOpen(true);
  const handleCloseModal = () => setIsModalOpen(false);

  const handleOverlayClick = (e) => {
    // Close the modal only if the user clicks on the overlay, not the modal content
    if (e.target.id === "modal-overlay") {
      handleCloseModal();
    }
  };

  return (
    <div className="relative">
      {/* Button to Open Modal */}
      <button onClick={handleOpenModal} style={{ textShadow: '0 0 3px rgba(255,255,255,0.8), 0 0 3px rgba(34,211,238,0.1)' }} className="py-3 px-5 m-1 rounded-md drop-shadow-[0_0_5px_rgba(255,255,255,0.3)] hover:drop-shadow-[0_0_10px_rgba(255,255,255,0.5)] border-2 border-white bg-neutral-900 flex items-center text-lg text-white hover:bg-neutral-800   max-md:text-md max-md:w-100 fade-up duration-100">
        <FontAwesomeIcon icon={faEnvelope} size='lg'/><p className='ml-2 max-md:hidden '>Mail</p>
      </button>

      {/* Modal */}
      {isModalOpen && (
          <div id="modal-overlay" className=" fixed inset-0 bg-red-400 bg-opacity-20 backdrop-blur-sm flex items-center justify-center z-50" onClick={handleOverlayClick}>
          <div className="bg-black shadow-[0_0_7px_rgba(34,211,238,0.5)] p-6 max-lg:p-4 rounded-lg max-w-4xl w-fit max-h-screen my-3 mx-3 overflow-scroll relative">
         {/* Grid */}
              <div className="pointer-events-none absolute inset-0 opacity-30 bg-[linear-gradient(rgba(6,182,212,0.3)_1px,transparent_1px),linear-gradient(90deg,rgba(6,182,212,0.3)_1px,transparent_1px)] bg-[size:5px_20px]"></div>
              <h2 className="text-2xl  text-cyan-400 drop-shadow-[0_0_15px_rgba(34,211,238,0.8)] text-center mb-7">Choose an email option</h2>

            <div className="">
              {/* Option 1 */}
              <a href="mailto:anindyakbiswas5@gmail.com" className="block mb-1 shadow-[0_0_7px_rgba(34,211,238,0.5)] hover:shadow-[0_0_10px_rgba(34,211,238,1)] bg-cyan-950/20 hover:bg-cyan-950 text-cyan-200 px-4 py-4 rounded-t-md border border-cyan-400 duration-100 text-center">
                <FontAwesomeIcon icon={faUser} className=' me-2 opacity-80' />anindyakbiswas5@gmail.com
              </a>
              {/* Option 2 */}
              <a href="mailto:anindya_b@mfs.iitr.ac.in" className="block mb-2 shadow-[0_0_7px_rgba(34,211,238,0.5)] hover:shadow-[0_0_10px_rgba(34,211,238,1)] bg-cyan-950/20 hover:bg-cyan-950 text-cyan-200 px-4 py-4 rounded-b-md border border-cyan-400 duration-100 text-center">
                <FontAwesomeIcon icon={faBriefcase} className=' me-2 opacity-80' />anindya_b@mfs.iitr.ac.in
              </a>

              {/* Close Button */}
            {/* <button onClick={handleCloseModal} className="block text-neutral-100 mx-auto py-3 px-7 rounded-full bg-red-500 border duration-300 text-center">
              Close
            </button> */}
            </div>
            
          </div>
        </div>
      )}
    </div>
  );
}
