import React, { useState } from "react";
import { FontAwesomeIcon } from "@fortawesome/react-fontawesome";
import { faGithub} from "@fortawesome/free-brands-svg-icons";
import { faComputer } from "@fortawesome/free-regular-svg-icons"
import { faEllipsis, faMicrochip, faXmark } from "@fortawesome/free-solid-svg-icons";


export default function Skill({main_skills, other_skills, languages, libnframeworks}){


    const main_skillArray = (main_skills || "").split(", ").map((word, index) => (
        <div key={index} className=" bg-red-800/20 backdrop-blur-xl hover:bg-red-900/90 border-2 border-red-600 drop-shadow-[0_0_7px_rgba(255,0,0,0.5)] text-red-300 duration-100 mr-1 py-2 px-4 rounded-md mt-2 text-sm max-md:text-xs">
          <p style={{ textShadow: '0 0 15px rgba(255,0,0,0.5), 0 0 3px rgba(255,0,0,0.1)' }}>
          {word}
          </p>
          </div>
      ));


      const inModalPillClass = "bg-red-600/20 hover:bg-red-800/50 border border-red-600 shadow-[0_0_5px_rgba(255,0,0,0.5)] text-red-200 text-md mr-2 py-2 max-md:py-1 max-md:m-1 max-md:text-sm px-3 rounded-md mt-2 duration-100";
    
    const all_skillArray = (main_skills + ", " + other_skills || "").split(", ").map((word, index) => (
        <div key={index} className={inModalPillClass}>{word}</div>
      ));
    
      const languagesArray = (languages || "").split(", ").map((word, index) => (
        <div key={index} className={inModalPillClass}>{word}</div>
      ));


      const libnframeworkArray = (libnframeworks || "").split(", ").map((word, index) => (
        <div key={index} className={inModalPillClass}>{word}</div>
      ));





        const [isModalOpen, setIsModalOpen] = useState(false);
      
        const handleOpenModal = () => setIsModalOpen(true);
        const handleCloseModal = () => setIsModalOpen(false);
      
        const handleOverlayClick = (e) => {
          // Close the modal only if the user clicks on the overlay, not the modal content
          if (e.target.id === "modal-overlay") {
            handleCloseModal();
          }};


      return(
        <>
        <div className='flex flex-wrap mt-2 justify-center blur-reveal'>
          {/* <div className="py-2 px-4 bg-neutral-800 text-neutral-200 rounded-3xl mr-2">Skills : </div> */}
            {main_skillArray}
            <button className="blur-reveal bg-red-600/40 backdrop-blur-xl hover:bg-red-800/50 border-2 border-red-600 shadow-[0_0_15px_rgba(255,0,0,0.5)] text-red-200 duration-100 px-3 py-0 mt-2 rounded-xl" onClick={handleOpenModal}><FontAwesomeIcon icon={faEllipsis} size="md" s /></button>
        </div>



              {/* Modal */}
              {isModalOpen && (
                <div id="modal-overlay" className=" fixed inset-0 bg-red-400 bg-opacity-20 backdrop-blur-sm flex items-center justify-center z-50" onClick={handleOverlayClick}>
                  <div className="scan-reveal-noise bg-black max-sm:mb-10  shadow-[0_0_7px_rgba(34,211,238,0.5)] p-6 max-lg:p-4 rounded-lg max-w-3xl w-fit max-h-screen my-3 mx-3 overflow-scroll relative">
                  {/* Grid */}
                  <div className="pointer-events-none absolute inset-0 opacity-30 bg-[linear-gradient(rgba(6,182,212,0.3)_1px,transparent_1px),linear-gradient(90deg,rgba(6,182,212,0.3)_1px,transparent_1px)] bg-[size:5px_20px]"></div>
                 
                    {/* Close Button */}
                    <button 
                      onClick={handleCloseModal}
                      className="absolute top-4 right-4 text-cyan-400 hover:text-red-400 hover:rotate-90 duration-300 text-2xl hover:scale-110 z-50"
                      aria-label="Close modal"
                    >
                      <FontAwesomeIcon icon={faXmark} />
                    </button>

                    <h2 className="text-2xl mb-2 mt-1 ms-2 text-cyan-400 drop-shadow-[0_0_15px_rgba(34,211,238,0.8)] ">Skills</h2>
                    <div className="flex flex-wrap">
                      {all_skillArray}
                    </div>
                    <div className="flex-none mt-6 max-md:mt-5 ms-1 mb-2 text-sm text-cyan-400 drop-shadow-[0_0_15px_rgba(34,211,238,0.8)]">Libraries/Frameworks</div>
                      <div className="flex flex-wrap">
                        {libnframeworkArray}
                      </div>
                    <div className="flex-none mt-6 max-md:mt-5 ms-1 mb-2 text-sm text-cyan-400 drop-shadow-[0_0_15px_rgba(34,211,238,0.8)]">Languages</div>
                      <div className="flex flex-wrap mb-5">
                        {languagesArray}
                      </div>
                    
                  </div>
                </div>
              )}
        </>
      )
}
