import React from 'react'

export default function Info({ children, classlist=  "", id=null}) {
    let classes = `bg-black hover:bg-cyan-800/90 border-2 border-cyan-400 shadow-[0_0_7px_rgba(34,211,238,0.5)]  shadow-2xl hover:shadow-[0_0_10px_rgba(34,211,238,0.5)] duration-300 text-cyan-400 rounded-md px-5 py-3 m-1 text-xl digital-fade ${ classlist }`
    let last_classes = `px-3 py-3 m-4 rounded-3xl bg-red-600 flex items-center text-lg text-neutral-700 hover:bg-neutral-800 hover:text-neutral-50 hover:duration-500 max-md:px-6 max-md:py-8 max-md:text-md max-md:w-100 digital-fade flex-none ${ classlist }`
    return (
    <div >
        <div className=" bg-cyan-400/10  hover:bg-cyan-800/90 border-2 border-cyan-400 shadow-[0_0_7px_rgba(34,211,238,0.5)]  hover:shadow-[0_0_10px_rgba(34,211,238,0.5)] duration-100 text-cyan-400 rounded-md px-3 py-3 m-1 text-lg max-md:text-sm scan-reveal-noise" id={id}>
         <p style={{ textShadow: '0 0 3px rgba(34,211,238,0.5), 0 0 3px rgba(34,211,238,0.1)' }}>
        {children}
        </p>
        </div>
    </div>
  )
}
