import React from 'react'

export default function Social({children, link="#", tooltip=link}) {

  return (
    <a href={link} title={tooltip} target='_blank' style={{ textShadow: '0 0 3px rgba(255,255,255,0.8), 0 0 3px rgba(34,211,238,0.1)' }} download className='py-3 px-5 m-1 rounded-md drop-shadow-[0_0_5px_rgba(255,255,255,0.3)] hover:drop-shadow-[0_0_10px_rgba(255,255,255,0.5)] border-2 border-white bg-neutral-900 flex items-center text-lg text-white hover:bg-neutral-800   max-md:text-md max-md:w-100 fade-up duration-100'>
        

        {children}
    </a>
  )
}
